{"command":"eval","project_path":"<PROJECT>","code":"extends RefCounted
func run(editor, undo_redo):
	var root = editor.get_edited_scene_root()
	var h = undo_redo.get_history_undo_redo(undo_redo.get_object_history_id(root))
	var scripts = {}
	var stack = [root]
	while not stack.is_empty():
		var n = stack.pop_back()
		var rp = root.get_path_to(n)
		var key = "." if str(rp) == "" else str(rp)
		var s = n.get_script()
		scripts[key] = (str(s.resource_path) if s != null else null)
		for c in n.get_children():
			stack.push_back(c)
	return {"history": h.get_history_count(), "has_undo": h.has_undo(), "scripts": scripts}
"}

